SELECT VERSION(), @@sql_mode;
CREATE TEMPORARY TABLE d1_fixed (id INT PRIMARY KEY, report JSON NULL) ENGINE=InnoDB;
INSERT INTO d1_fixed VALUES (1,JSON_OBJECT('admitted',7)),(2,JSON_OBJECT('admitted',0)),(3,NULL),(4,JSON_OBJECT('other',1));
SET @local_report='{"admitted":999,"totalCandidates":3}';
PREPARE heartbeat FROM 'UPDATE d1_fixed SET report=JSON_SET(?, ''$.admitted'', COALESCE(CAST(JSON_UNQUOTE(JSON_EXTRACT(report, ''$.admitted'')) AS SIGNED), 0)) WHERE id=?';
SET @id=1;
SET @id=1;
EXECUTE heartbeat USING @local_report,@id;
SELECT 'heartbeat-1' AS step, id, JSON_TYPE(JSON_EXTRACT(report,'$.admitted')) AS type, JSON_EXTRACT(report,'$.admitted') AS value, (JSON_TYPE(JSON_EXTRACT(report,'$.admitted'))='INTEGER' AND JSON_EXTRACT(report,'$.admitted')=7) AS pass FROM d1_fixed WHERE id=1;
SET @id=1;
EXECUTE heartbeat USING @local_report,@id;
SELECT 'heartbeat-2' AS step, id, JSON_TYPE(JSON_EXTRACT(report,'$.admitted')) AS type, JSON_EXTRACT(report,'$.admitted') AS value, (JSON_TYPE(JSON_EXTRACT(report,'$.admitted'))='INTEGER' AND JSON_EXTRACT(report,'$.admitted')=7) AS pass FROM d1_fixed WHERE id=1;
SET @id=1;
EXECUTE heartbeat USING @local_report,@id;
