UPDATE d1_fixed SET report=JSON_SET(COALESCE(report,JSON_OBJECT()),'$.admitted',CAST(COALESCE(CAST(JSON_UNQUOTE(JSON_EXTRACT(report, '$.admitted')) AS SIGNED), 0)+1 AS SIGNED)) WHERE id=2;
